// F35: one place that formats money, percentages and statistical results for every page.
// Pure functions with no Next.js imports, so pages stay thin and tests can call them directly.
// Wording follows docs/DESIGN.md: "significant" only when p < 0.05, and a lone n = is printed with the claim.

/** U+2212, not the ASCII hyphen: a negative amount reads as a minus, not a dash. */
const MINUS = "−";

/** Missing, NaN and infinite values have no display form, so they all read as "n/a". */
const missing = (n: number | null): boolean => n === null || !Number.isFinite(n);

/**
 * Money in USD, two decimals with thousands separators: `1234.56 -> "$1,234.56"`.
 * A negative amount puts the minus before the dollar sign: `-3 -> "−$3.00"`. Missing or non-finite is "n/a".
 */
export function usd(n: number | null): string {
  if (missing(n)) return "n/a";
  const body = Math.abs(n as number).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${(n as number) < 0 ? MINUS : ""}$${body}`;
}

/**
 * A share in [0, 1] as a percent: `0.4213 -> "42.1%"`. `digits` is the number of decimal places (default 1).
 * Missing or non-finite is "n/a". A negative share keeps its sign, the same minus money uses.
 */
export function pct(share: number | null, digits = 1): string {
  if (missing(share)) return "n/a";
  const scaled = (share as number) * 100;
  const body = `${Math.abs(scaled).toFixed(digits)}%`;
  return `${scaled < 0 ? MINUS : ""}${body}`;
}

/**
 * A p-value with its sample size. Below 0.001 it reads as an inequality: `0.0004 -> "p < 0.001"`.
 * Otherwise three decimals: `0.031 -> "p = 0.031"`. At or above 0.05 it says so, and carries n:
 * `0.24, 18 -> "p = 0.240 (not significant at n = 18)"`. The suffix is keyed on the value, not the rounding.
 */
export function pValue(p: number, n: number): string {
  const body = p < 0.001 ? "p < 0.001" : `p = ${p.toFixed(3)}`;
  return p >= 0.05 ? `${body} (not significant at n = ${n})` : body;
}

