// names; the sample values in the last block of each section come from the real published review
// (reports/rajkaria__roster/review.json), so the shapes match what a page actually hands these functions.
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { Review } from "../web/lib/types.ts";
import { pct, pValue, usd } from "../web/lib/format.ts";

const review: Review = JSON.parse(readFileSync(join(import.meta.dir, "..", "reports", "rajkaria__roster", "review.json"), "utf8"));

/** U+2212 MINUS SIGN, written out so a stray ASCII hyphen fails loudly. */
const MINUS = "−";

describe("usd", () => {
  test("two decimals with thousands separators", () => {
    expect(usd(1234.56)).toBe("$1,234.56");
    expect(usd(19.0633692)).toBe("$19.06");
    expect(usd(0)).toBe("$0.00");
    expect(usd(999.999)).toBe("$1,000.00");
  });

  test("a negative amount carries a true minus before the dollar sign", () => {
    expect(usd(-3)).toBe(`${MINUS}$3.00`);
    expect(usd(-1234.567)).toBe(`${MINUS}$1,234.57`);
    expect(usd(-3)).not.toContain("-");
  });

  test("null and non-finite values read n/a", () => {
    for (const v of [null, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
      expect(usd(v)).toBe("n/a");
    }
  });

  test("the published review's spend formats with cents", () => {
    const spend = review.setups[0]!.spend_usd!;
    expect(usd(spend)).toBe("$19.06");
  });
});

describe("pct", () => {
  test("a share becomes a percent with one decimal by default", () => {
    expect(pct(0.4213)).toBe("42.1%");
    expect(pct(0)).toBe("0.0%");
    expect(pct(1)).toBe("100.0%");
  });

  test("digits sets the decimal places", () => {
    expect(pct(0.4213, 2)).toBe("42.13%");
    expect(pct(0.4213, 0)).toBe("42%");
    expect(pct(0.0399, 2)).toBe("3.99%");
  });

  test("a negative share keeps its sign, the same minus money uses", () => {
    expect(pct(-0.05)).toBe(`${MINUS}5.0%`);
  });

  test("null and non-finite values read n/a", () => {
    for (const v of [null, Number.NaN, Number.POSITIVE_INFINITY]) {
      expect(pct(v)).toBe("n/a");
    }
  });

  test("the published review's unattended share formats as a percent", () => {
    expect(pct(review.setups[1]!.unattended)).toBe("63.6%");
  });
});

describe("pValue", () => {
  test("below 0.001 reads as an inequality", () => {
    expect(pValue(0.0004, 30)).toBe("p < 0.001");
    expect(pValue(0, 30)).toBe("p < 0.001");
  });

  test("otherwise three decimals", () => {
    expect(pValue(0.031, 30)).toBe("p = 0.031");
    expect(pValue(0.001, 30)).toBe("p = 0.001");
    expect(pValue(0.0499, 30)).toBe("p = 0.050");
  });

  test("at or above 0.05 it says so and carries n", () => {
    expect(pValue(0.05, 18)).toBe("p = 0.050 (not significant at n = 18)");
    expect(pValue(0.24, 18)).toBe("p = 0.240 (not significant at n = 18)");
    expect(pValue(1, 4)).toBe("p = 1.000 (not significant at n = 4)");
  });

  test("just below 0.05 is still a claim, with no suffix", () => {
    expect(pValue(0.049, 40)).toBe("p = 0.049");
    expect(pValue(0.0009, 40)).not.toContain("n =");
  });

  test("the published review's test is not significant at its four pairs", () => {
    expect(review.p_value).not.toBeNull();
    expect(pValue(review.p_value!, review.setups.length)).toBe("p = 1.000 (not significant at n = 4)");
  });
});

